first_input = input("Enter your name: ") # this will take input from the user and store it in the variable first_input in the for of string
second_input = int(input("Enter your age: ")) # this will take input from the user and store it in the variable second_input in the form of integer
third_input = float(input("Enter your height: ")) # this will take input from the user and store it in the variable third_input in the form of float
fourth_input = bool(input("Enter your gender (True for male, False for female): ")) # this will take input from the user and store it in the variable fourth_input in the form of boolean
print(f"first_input: {first_input}, type: {type(first_input)}") # this will print the value of first_input and its data type
print(f"second_input: {second_input}, type: {type(second_input)}") # this will print the value of second_input and its data type
print(f"third_input: {third_input}, type: {type(third_input)}") # this will print the value of third_input and its data type
print(f"fourth_input: {fourth_input}, type: {type(fourth_input)}") # this will print the value of fourth_input and its data type